// 原改道只安装计划；同捕获原钱包/行囊不动，不按新报价重收或重算过去费用。
#include "private_shop_travel_replan_source.hpp"
#include "resident/domains/travel/travel.hpp"
#include "resident/storage/common_codec.hpp"
#include <limits>
namespace hanmo::resident {
struct PrivateShopTravelReplanBoundary::State {
 const CommonStore* common=nullptr;const TravelState* travel=nullptr;const TravelCatalog* catalog=nullptr;
 std::shared_ptr<const ResourceExecutionCaptureIdentity> capture;
 CommonState original;TravelState original_travel;PreparedTravelOp command;
 TravelOriginalPlanSnapshot snapshot;StableId action,actor,wallet,inventory;std::size_t recipe_begin=0;
};
// 同栈不可变前界只有本叶可读，调用者不能覆盖原quote/旧计划或原余额。
struct PrivateShopTravelReplanAccess {static const auto& state(const PrivateShopTravelReplanBoundary& b){return b.state_;}};
namespace {
// 仅投影本次原人/行动/两容器和全局事实头；其余资源仍须原coverage完整收尾。
CommonState selected_common(const CommonStore& c,const StableId& actor,const StableId& action,const StableId& wallet,const StableId& inventory){CommonState s;s.identity=c.state().identity;s.next_instance_id=c.state().next_instance_id;s.facts=c.state().facts;const auto* a=c.state().actors.find(actor);if(a)s.actors.insert(actor,*a);if(const auto* v=c.action(action))s.actions.insert(action,*v);if(const auto* v=c.wallet(wallet))s.wallets.insert(wallet,*v);if(const auto* v=c.inventory(inventory))s.inventories.insert(inventory,*v);return s;}
bool same_location(const Location&a,const Location&b){return compare_boundary(boundary::encode_location(a),boundary::encode_location(b)).exact();}
bool same_point(PointI a,PointI b){return a.x==b.x&&a.y==b.y;}
bool same_points(const std::vector<PointI>&a,const std::vector<PointI>&b){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(!same_point(a[i],b[i]))return false;return true;}
bool same_destination(const TravelDestination&a,const TravelDestination&b){if(a.index()!=b.index())return false;if(auto id=std::get_if<StableId>(&a))return *id==std::get<StableId>(b);return same_point(std::get<PointI>(a),std::get<PointI>(b));}
bool same_quote(const TravelQuote&a,const TravelQuote&b){return a.duration==b.duration&&a.cost==b.cost&&a.budget==b.budget&&a.starting_load==b.starting_load&&a.money_per_tick==b.money_per_tick&&a.fatigue_per_tick==b.fatigue_per_tick&&a.map_id==b.map_id&&a.origin==b.origin&&a.mode==b.mode&&a.payer_wallet_id==b.payer_wallet_id&&same_points(a.points,b.points)&&same_destination(a.destination,b.destination)&&bool(a.road)==bool(b.road)&&(!a.road||(a.road->path==b.road->path&&a.road->returning==b.road->returning));}
bool same_action(const ActionCoreView&a,const ActionCoreView&b){return a.id==b.id&&a.kind==b.kind&&a.actor_id==b.actor_id&&a.participants==b.participants&&a.start_tick==b.start_tick&&a.remaining_ticks==b.remaining_ticks;}
// 原导出包含字段存在性/顺序；另外核载荷内部id，不能只比JSON表键。
bool same_travel(const TravelState&a,const TravelState&b){
 // 即使原可选键未输出，其typed值/存在旗标和原字段序仍须不变，不能只比编码后的可见键。
 if(a.actions.size()!=b.actions.size()||a.road_actions.size()!=b.road_actions.size()||a.journey_facts.size()!=b.journey_facts.size()||a.itineraries.size()!=b.itineraries.size())return false;
 for(const auto& row:a.actions.rows()){const auto* v=b.actions.find(row.first);const auto& p=row.second;if(!v||p.has_encounter_id!=v->has_encounter_id||p.has_met_actions!=v->has_met_actions||p.encounter_id!=v->encounter_id||p.met_actions!=v->met_actions||p.field_order!=v->field_order)return false;}
 for(const auto& row:a.road_actions.rows()){const auto* v=b.road_actions.find(row.first);const auto& p=row.second;if(!v||p.has_terrain!=v->has_terrain||p.has_paused!=v->has_paused||p.has_reverse_first!=v->has_reverse_first||p.has_encounter_id!=v->has_encounter_id||p.has_met_actions!=v->has_met_actions||p.paused!=v->paused||p.reverse_first!=v->reverse_first||p.encounter_id!=v->encounter_id||p.met_actions!=v->met_actions||p.field_order!=v->field_order)return false;}
 for(const auto& row:a.journey_facts.rows()){const auto* v=b.journey_facts.find(row.first);if(!v||row.second.id!=v->id||row.second.field_order!=v->field_order)return false;}
 for(const auto& row:a.itineraries.rows()){const auto* v=b.itineraries.find(row.first);if(!v||row.second.field_order!=v->field_order)return false;}
 auto x=export_travel_state(a),y=export_travel_state(b);return x.ok&&y.ok&&compare_boundary(x.value,y.value).exact();}
bool same_snapshot(const TravelOriginalPlanSnapshot&a,const TravelOriginalPlanSnapshot&b){if(!same_action(a.action,b.action)||!same_location(a.location,b.location)||bool(a.params)!=bool(b.params)||bool(a.terrain_plan)!=bool(b.terrain_plan))return false;TravelState x,y;auto insert=[](TravelState& t,const TravelOriginalPlanSnapshot& s){if(s.params)std::visit([&](const auto&p){using T=std::decay_t<decltype(p)>;if constexpr(std::is_same_v<T,RoadTravelParams>)t.road_actions.insert(s.action.id,p);else t.actions.insert(s.action.id,p);},*s.params);if(s.terrain_plan)t.journey_facts.insert(s.terrain_plan->id,*s.terrain_plan);};insert(x,a);insert(y,b);return same_travel(x,y);}
}
namespace {
bool replan(const PreparedTravelOp& op){return op.quote&&(std::holds_alternative<RerouteCommand>(op.command)||std::holds_alternative<ReturnTravelCommand>(op.command));}
// 原返程无额外载荷；改道的目的地/途经点也必须与原prepare完全一致。
bool same_replan(const PreparedTravelOp&a,const PreparedTravelOp&b){if(!replan(a)||!replan(b)||a.actor_id!=b.actor_id||a.command.index()!=b.command.index()||!same_quote(*a.quote,*b.quote))return false;if(const auto* x=std::get_if<RerouteCommand>(&a.command)){const auto& y=std::get<RerouteCommand>(b.command);return same_destination(x->destination,y.destination)&&x->via==y.via;}return true;}
}
Outcome<PrivateShopTravelReplanBoundary> capture_private_shop_travel_replan_boundary(const CommonStore& c,const TravelState& t,const TravelCatalog& catalog,const PreparedTravelOp& command){
 const auto fail=[&](const StableId& code)->Outcome<PrivateShopTravelReplanBoundary>{return {false,{},common_failure(code,command.actor_id).error};};const auto token=c.resource_execution_capture_identity();const auto* actor=c.actor(command.actor_id);if(!token||!actor||!replan(command)||t.rescues.find(actor->action_id))return fail("PrivateShopTravelReplanBoundaryRequired");auto old=capture_original_travel_plan_snapshot(c,t,actor->action_id);if(!old.ok||!old.value.params)return fail("PrivateShopTravelReplanOriginalRequired");const auto payer=std::visit([](const auto&p){return p.payer_wallet_id;},*old.value.params);const auto* wallet=c.wallet(payer);const auto* bag=c.inventory(actor->inventory_id);if(!wallet||!bag)return fail("PrivateShopTravelReplanAssetsRequired");const auto& q=*command.quote;
 if(std::holds_alternative<RoadTravelParams>(*old.value.params)){if(!q.road||q.road->path.empty()||!q.road->returning||!std::holds_alternative<OnRouteLocation>(actor->location))return fail("PrivateShopTravelReplanQuoteRequired");}else if(q.road||q.payer_wallet_id!=payer||q.points.size()<2||c.state().next_instance_id<1||c.state().next_instance_id==std::numeric_limits<Integer>::max())return fail("PrivateShopTravelReplanQuoteRequired");
 auto b=std::make_shared<PrivateShopTravelReplanBoundary::State>();b->common=&c;b->travel=&t;b->catalog=&catalog;b->capture=token;b->actor=actor->id;b->action=actor->action_id;b->wallet=payer;b->inventory=bag->id;b->snapshot=std::move(old.value);b->original=selected_common(c,b->actor,b->action,b->wallet,b->inventory);b->original_travel=t;b->command=command;b->recipe_begin=c.resource_execution_drafts().size();PrivateShopTravelReplanBoundary out;out.state_=std::move(b);return {true,std::move(out),{}};
}
Outcome<PrivateShopTravelReplanSource> read_private_shop_travel_replan(const CommonStore& c,const TravelState& t,const TravelCatalog& catalog,const PrivateShopTravelReplanBoundary& boundary_value,const TravelControlDraft& draft){
 const auto fail=[](const StableId& code)->Outcome<PrivateShopTravelReplanSource>{return {false,{},common_failure(code).error};};const auto& b=PrivateShopTravelReplanAccess::state(boundary_value);if(!b||b->common!=&c||b->travel!=&t||b->catalog!=&catalog||!b->capture||b->capture!=c.resource_execution_capture_identity()||b->recipe_begin!=c.resource_execution_drafts().size()||draft.source_tick!=b->original.identity.tick||!same_replan(b->command,draft.original_control)||!same_snapshot(b->snapshot,draft.before))return fail("PrivateShopTravelReplanScopeMismatch");
 auto expected=b->original;auto travel=b->original_travel;auto* actor=expected.actors.find(b->actor);const auto& q=*b->command.quote;expected.actions.find(b->action)->remaining_ticks=std::max<Integer>(1,q.duration);
 if(q.road){auto p=*travel.road_actions.find(b->action);p.path=q.road->path;p.edge_index=0;p.returning=*q.road->returning;p.reverse_first=p.returning;p.paused=false;for(auto pair:{std::make_pair("reverse_first",&p.has_reverse_first),std::make_pair("paused",&p.has_paused)}){if(!*pair.second&&!p.field_order.empty())p.field_order.push_back(pair.first);*pair.second=true;}auto location=actor->location;auto finished=finish_road_leg(catalog,expected.identity.tick,p,location);if(!finished.ok)return {false,{},finished.error};const auto* old=std::get_if<OnRouteLocation>(&actor->location);const auto* next=std::get_if<OnRouteLocation>(&location);if(!old||!next||old->edge_id!=next->edge_id||old->origin!=next->origin)actor->location_order.clear();actor->location=location;travel.road_actions.set(b->action,std::move(p));
 }else{const auto* prior=travel.actions.find(b->action);const auto credit=prior->travel_credit>=0&&prior->travel_credit<=2147483647LL?prior->travel_credit:0;const auto met=prior->met_actions;const auto id="journey:"+std::to_string(expected.next_instance_id++);if(expected.facts.find(id)||travel.journey_facts.find(id))return fail("PrivateShopTravelReplanPlanCollision");expected.facts.insert(id,{id,"terrain_journey","travel",{}});TerrainJourneyFact f;f.id=id;f.actor_id=b->actor;f.action_id=b->action;f.map_id=q.map_id;f.mode=q.mode;f.tick=expected.identity.tick;f.budget=q.budget;f.starting_load=q.starting_load;f.origin=q.points.front();f.destination=q.destination;f.points=q.points;travel.journey_facts.set(id,std::move(f));TerrainTravelParams p;p.plan_id=id;p.map_id=q.map_id;p.origin=q.origin;p.payer_wallet_id=q.payer_wallet_id;p.mode=q.mode;p.budget=q.budget;p.travel_credit=credit;p.money_per_tick=q.money_per_tick;p.fatigue_per_tick=q.fatigue_per_tick;p.points.assign(q.points.begin()+1,q.points.end());p.destination=q.destination;p.met_actions=met;travel.actions.set(b->action,std::move(p));actor->location=WildernessLocation{q.map_id,q.origin,q.points.front()};actor->location_order.clear();}
 if(!compare_boundary(encode_common_state(expected),encode_common_state(selected_common(c,b->actor,b->action,b->wallet,b->inventory))).exact()||!same_travel(travel,t))return fail("PrivateShopTravelReplanActualMismatch");auto after=capture_original_travel_plan_snapshot(c,t,b->action);if(!after.ok||!same_snapshot(after.value,draft.after))return fail("PrivateShopTravelReplanActualMismatch");return {true,{c.state().identity,draft},{}};
}
}
